"""Carga 5 (ampliação, 2026-09-29): itens extras de FAQ de preparo, pesquisados por agentes e filtrados pelas regras do projeto."""
ITENS = [
    ('Urografia excretora', 'O que vou sentir quando injetarem o contraste na veia?', 'É comum sentir calor pelo corpo, gosto metálico na boca e, às vezes, enjoo ou vontade de vomitar. Costuma passar rápido. Se algo incomodar muito, avise logo a equipe.', ('AbcMed', 'https://abc.med.br/exames-e-procedimentos/urografia-excretora-como-e-este-exame')),
    ('Urografia excretora', 'Uso remédio para diabetes com metformina. Preciso avisar antes da urografia excretora?', 'Sim, avise a equipe no agendamento. Esse remédio costuma exigir uma pausa antes e depois do exame, pelo tempo indicado no seu preparo. Siga exatamente o que a unidade orientar.', ('X-LEME Diagnóstico por Imagem', 'https://www.xleme.com.br/preparos-urografia-excretora.html')),
    ('Urografia excretora', 'Como é feita a urografia excretora, passo a passo?', 'Você deita na mesa e são feitas algumas imagens antes do contraste. Depois o contraste entra pela veia do braço e novas imagens são feitas em intervalos, acompanhando o caminho do contraste pelos rins, ureteres e bexiga.', ('AbcMed', 'https://abc.med.br/exames-e-procedimentos/urografia-excretora-como-e-este-exame')),
    ('Urografia excretora', 'A urografia excretora demora muito?', 'O tempo é moderado, mas pode se prolongar conforme a rapidez com que seus rins eliminam o contraste. Vá sem pressa e sem outros compromissos logo em seguida.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-urografia-excretora')),
    ('Urografia excretora', 'O que devo levar para a urografia excretora?', 'Leve o pedido médico, documento com foto, carteirinha do convênio e exames de imagem anteriores. Se você tem problema nos rins, leve também o exame de função renal recente.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-urografia-excretora')),
    ('Urografia excretora', 'Posso ir de joias, óculos e dentadura móvel para a urografia excretora?', 'O ideal é deixar em casa ou retirar antes das imagens joias, óculos, aparelhos dentários móveis e qualquer objeto de metal. Evite também roupas com zíper ou fivelas na região da barriga.', ('Eigier Diagnósticos', 'https://eigierdiagnosticos.com.br/blog/urografia-excretora/')),
    ('Urografia excretora', 'Preciso beber água depois da urografia excretora?', 'Sim, em geral é recomendado se hidratar bem depois do exame para ajudar o corpo a eliminar o contraste mais rápido. Siga a orientação da unidade se você tiver alguma restrição de líquidos.', ('AbcMed', 'https://abc.med.br/exames-e-procedimentos/urografia-excretora-como-e-este-exame')),
    ('Urografia excretora', 'Apareceu coceira ou manchas na pele depois da urografia excretora. O que faço?', 'Coceira, manchas ou inchaço podem ser sinais de reação ao contraste. Avise imediatamente a equipe se ainda estiver na unidade. Se falta de ar ou inchaço na garganta aparecerem, procure atendimento de urgência.', ('Eigier Diagnósticos', 'https://eigierdiagnosticos.com.br/blog/urografia-excretora/')),
    ('Urografia excretora', 'Vão me pedir para urinar no meio da urografia excretora?', 'Pode ser que sim. Perto do fim do exame às vezes se pede que você esvazie a bexiga para uma imagem adicional. A equipe avisa na hora.', ('Eigier Diagnósticos', 'https://eigierdiagnosticos.com.br/blog/urografia-excretora/')),
    ('Urografia excretora', 'Preciso ficar parado durante as imagens da urografia excretora?', 'Sim, ficar quieto ajuda a deixar as imagens nítidas. Você também pode ser chamado a mudar de posição e a segurar a respiração por instantes, sempre com orientação do técnico.', ('Eigier Diagnósticos', 'https://eigierdiagnosticos.com.br/blog/urografia-excretora/')),
    ('Urografia excretora', 'Tenho um problema nos rins ou só um rim. Isso muda algo para a urografia excretora?', 'Avise a equipe ao agendar. Nesses casos costuma ser pedido um exame de função dos rins recente e o exame pode demorar mais, porque depende da eliminação do contraste.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-urografia-excretora')),
    ('Urografia excretora', 'Meu filho vai fazer a urografia excretora. Como funciona o jejum e o acompanhante?', 'O tempo de jejum para crianças é menor e varia conforme a idade, por isso siga o preparo entregue pela unidade. Menores de idade precisam de um responsável adulto durante o exame.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-urografia-excretora')),
    ('Urografia excretora', 'Estou com atraso menstrual. Posso fazer a urografia excretora?', 'Se houver gravidez, suspeita ou dúvida, atraso menstrual incluído, o exame não deve ser feito por causa da radiação. Avise a equipe no agendamento para reorganizar a data.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-urografia-excretora')),
    ('Urografia excretora', 'Preciso chegar mais cedo para a urografia excretora?', 'Sim, é recomendado chegar com antecedência ao horário marcado para fazer o cadastro e responder ao questionário da equipe. Em alguns locais o exame precisa ser agendado pessoalmente.', ('X-LEME Diagnóstico por Imagem', 'https://www.xleme.com.br/preparos-urografia-excretora.html')),
    ('Urografia excretora', 'Quem me passa o resultado da urografia excretora?', 'As imagens são analisadas por um radiologista, que emite o laudo. Em geral ele é entregue à parte, conforme o prazo da unidade, e a interpretação fica com o profissional que pediu o exame.', ('Eigier Diagnósticos', 'https://eigierdiagnosticos.com.br/blog/urografia-excretora/')),
    ('Urografia excretora', 'Tenho dificuldade de ficar parado. Existe algum recurso para a urografia excretora?', 'Em casos de dificuldade para ficar imóvel, a sedação pode ser considerada em alguns serviços. Avise a equipe no agendamento para que combinem a melhor forma de fazer o exame.', ('Tua Saúde', 'https://www.tuasaude.com/en/intravenous-pyelogram/')),
    ('Uretrocistografia miccional', 'Preciso de jejum ou dieta especial para a uretrocistografia miccional?', 'Depende da unidade. Algumas não exigem jejum e outras pedem uma dieta líquida leve ou um jejum curto. Siga o preparo que você recebeu no agendamento.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-uretrocistografia-miccional-adulto')),
    ('Uretrocistografia miccional', 'Vão usar anestesia na uretrocistografia miccional?', 'Em muitos serviços é aplicado um anestésico local na região para reduzir o incômodo da passagem da sonda. Pergunte à equipe como será no seu caso.', ('Tua Saúde', 'https://www.tuasaude.com/uretrocistografia/')),
    ('Uretrocistografia miccional', 'Como é feita a uretrocistografia miccional, passo a passo?', 'Você deita na mesa, a região é higienizada e uma sonda fina leva o contraste até a bexiga. São feitas imagens enquanto ela enche e depois você urina, para observar o caminho do contraste. No fim a sonda é retirada.', ('Crya', 'https://crya.com.br/seo/uretrocistografia-adulta-procedimento-indicacoes-e-preparacao/')),
    ('Uretrocistografia miccional', 'Vou precisar urinar deitado durante a uretrocistografia miccional?', 'Sim, faz parte do exame. Você urina na própria mesa, com a equipe organizando toalhas ou recipiente. É normal ter vergonha, mas é uma etapa de rotina para eles.', ('Dr. Anselmo Hoffmann', 'https://dranselmohoffmann.com.br/uretrocistografia-miccional-retrograda-cum/')),
    ('Uretrocistografia miccional', 'Quanto tempo dura a uretrocistografia miccional?', 'Em geral é um exame de duração moderada, que pode se estender conforme a função dos rins e o tempo que a bexiga leva para esvaziar. Reserve a manhã ou a tarde sem outros compromissos.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-uretrocistografia-miccional-adulto')),
    ('Uretrocistografia miccional', 'Estou com sintomas de infecção urinária. Posso fazer a uretrocistografia miccional?', 'Avise a equipe antes, porque o exame não deve ser feito se houver suspeita ou confirmação de infecção urinária. Ele costuma ser remarcado para depois do tratamento.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-uretrocistografia-miccional-adulto')),
    ('Uretrocistografia miccional', 'Posso fazer a uretrocistografia miccional se estiver grávida ou com atraso menstrual?', 'Se houver gravidez, suspeita ou dúvida, o exame precisa ser avaliado antes por causa da radiação. Avise a equipe no agendamento para que orientem a melhor conduta.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-uretrocistografia-miccional-adulto')),
    ('Uretrocistografia miccional', 'O que é normal e o que não é depois da uretrocistografia miccional?', 'É comum ter uma leve ardência nas primeiras vezes que urinar e a urina ficar meio rosada. Beba bastante líquido para ajudar. Avise a equipe ou procure atendimento se surgirem dor, febre ou sangue na urina.', ('Dr. Anselmo Hoffmann', 'https://dranselmohoffmann.com.br/uretrocistografia-miccional-retrograda-cum/')),
    ('Uretrocistografia miccional', 'Tenho alergia a iodo ou látex. Preciso avisar antes da uretrocistografia miccional?', 'Sim. O contraste tem iodo e a sonda pode ter materiais que causam reação em algumas pessoas. Conte à equipe sobre qualquer alergia, inclusive a medicamentos.', ('Tua Saúde', 'https://www.tuasaude.com/uretrocistografia/')),
    ('Uretrocistografia miccional', 'Uso remédio para diabetes ou anticoagulante. Preciso informar na uretrocistografia miccional?', 'Sim, informe todos os remédios em uso, principalmente os de diabetes e os anticoagulantes, para que a equipe oriente o que fazer no seu preparo. Não pare nenhum por conta própria.', ('Tua Saúde', 'https://www.tuasaude.com/uretrocistografia/')),
    ('Uretrocistografia miccional', 'Meu filho vai fazer a uretrocistografia miccional. Como preparo a criança?', 'Explique com calma e linguagem simples o que vai acontecer, inclusive que ele vai urinar na mesa. Levar chupeta, cobertor ou brinquedo ajuda. Um adulto precisa acompanhar, e em alguns casos a equipe pode indicar sedação.', ('Dr. Anselmo Hoffmann', 'https://dranselmohoffmann.com.br/uretrocistografia-miccional-retrograda-cum/')),
    ('Uretrocistografia miccional', 'Devo levar exames de urina para a uretrocistografia miccional?', 'Algumas unidades pedem exame de urina ou urocultura recente e checam se há sinais de infecção antes de começar. Leve também exames de imagem anteriores relacionados ao problema.', ('FIDI', 'https://fidi.org.br/docs/exames/preparos/raio-x/adulto/preparo_para_exame_de_radiografia_contrastada_uretrocistografia_miccional_e_retrograda_adulto.pdf?_t=1711626836')),
    ('Uretrocistografia miccional', 'Posso voltar às minhas atividades depois da uretrocistografia miccional?', 'Em geral sim, você pode retomar a rotina logo depois, a menos que a equipe oriente diferente. Beba água e urine com frequência para eliminar o contraste.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-uretrocistografia-miccional-adulto')),
    ('Uretrocistografia miccional', 'Posso levar meu filho pequeno como acompanhante na uretrocistografia miccional?', 'Não é indicado. A unidade costuma não ter equipe para cuidar de crianças durante o exame de outra pessoa. Se possível, deixe-as com alguém e venha com um acompanhante adulto.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/raio-x-uretrocistografia-miccional-adulto')),
    ('Uretrocistografia miccional', 'Posso ir com joias e roupas com metal para a uretrocistografia miccional?', 'Retire joias e acessórios de metal e use roupas fáceis de tirar. Você provavelmente vai trocar por uma roupa da unidade.', ('Tua Saúde', 'https://www.tuasaude.com/uretrocistografia/')),
    ('Histerossalpingografia', 'A histerossalpingografia dói?', 'Costuma causar um desconforto parecido com cólica menstrual, com sensação de pressão, que passa logo depois do exame. A intensidade varia de pessoa para pessoa e, para a maioria, é tolerável.', ('Flávia Starling', 'https://flaviastarling.com.br/blog/histerossalpingografia-o-que-e-quando-e-indicada/')),
    ('Histerossalpingografia', 'Posso tomar remédio para cólica antes da histerossalpingografia?', 'Algumas unidades orientam tomar um antiespasmódico ou analgésico antes para reduzir o desconforto. Siga o que estiver no seu preparo e leve o que costuma usar para a dor, caso a equipe permita.', ('Mater Prime', 'https://materprime.com.br/histerossalpingografia-hsg/')),
    ('Histerossalpingografia', 'Quanto tempo dura a histerossalpingografia?', 'A duração varia conforme o serviço. Em geral o exame em si é relativamente rápido, mas o tempo total na unidade inclui cadastro e preparo. Reserve o período sem outros compromissos.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/histerossalpingografia')),
    ('Histerossalpingografia', 'Estou com sangramento vaginal no dia marcado. Posso fazer a histerossalpingografia?', 'Avise a equipe. Sangramento vaginal no momento é um motivo para não realizar o exame naquele dia, e ele costuma ser remarcado dentro da fase correta do ciclo.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/histerossalpingografia')),
    ('Histerossalpingografia', 'Estou com corrimento ou infecção. Posso fazer a histerossalpingografia?', 'Avise antes. Com corrimento ou infecção genital ativa o exame geralmente não é feito, para evitar complicações. Ele será remarcado quando você estiver liberada.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/histerossalpingografia')),
    ('Histerossalpingografia', 'Preciso fazer teste de gravidez antes da histerossalpingografia?', 'Algumas unidades exigem um exame de gravidez recente no dia do procedimento, e sem ele o exame não é feito. O exame não deve ser realizado se houver gravidez ou suspeita, por causa da radiação.', ('Ecomax', 'https://ecomax-cdi.com.br/Preparos/RX/RX-PREPARO_PARA_HISTEROSSALPINGOGRAFIA.pdf')),
    ('Histerossalpingografia', 'O que levar para a histerossalpingografia?', 'Leve pedido médico original, documento com foto, carteirinha do convênio, exames pélvicos anteriores e, se a unidade pedir, o termo de consentimento assinado e o resultado do teste de gravidez.', ('Ecomax', 'https://ecomax-cdi.com.br/Preparos/RX/RX-PREPARO_PARA_HISTEROSSALPINGOGRAFIA.pdf')),
    ('Histerossalpingografia', 'Que roupa e o que mais devo levar para ficar confortável na histerossalpingografia?', 'Vá com roupa leve e confortável e leve um absorvente, pois pode haver cólica e um pequeno sangramento depois. Também vale planejar um período de descanso após o exame.', ('Omni Diagnóstico', 'https://omnidiag.com.br/histerossalpingografia/')),
    ('Histerossalpingografia', 'Posso fazer depilação antes da histerossalpingografia?', 'Alguns serviços pedem para evitar depilar a região logo antes, pois a pele pode ficar mais sensível. Siga o seu preparo e, na dúvida, pergunte à equipe.', ('Omni Diagnóstico', 'https://omnidiag.com.br/histerossalpingografia/')),
    ('Histerossalpingografia', 'É normal sangrar depois da histerossalpingografia?', 'Um pequeno sangramento e uma cólica leve são esperados. Procure atendimento se houver sangramento intenso, febre, dor forte, enjoo ou vômitos, pois podem indicar necessidade de avaliação.', ('Mater Prime', 'https://materprime.com.br/histerossalpingografia-hsg/')),
    ('Histerossalpingografia', 'Posso voltar ao trabalho depois da histerossalpingografia?', 'Na maioria dos casos você retoma as atividades normais no mesmo dia, mas pode sentir um leve desconforto pélvico por um tempo. Se puder, planeje uma rotina mais tranquila.', ('Mater Prime', 'https://materprime.com.br/histerossalpingografia-hsg/')),
    ('Histerossalpingografia', 'Quando posso ter relações sexuais depois da histerossalpingografia?', 'Em geral, orienta-se esperar até parar qualquer sangramento leve e seguir o prazo que a equipe informar para o seu caso.', ('Omni Diagnóstico', 'https://omnidiag.com.br/histerossalpingografia/')),
    ('Histerossalpingografia', 'Tenho alergia a contraste com iodo. Posso fazer a histerossalpingografia?', 'Avise a equipe antes. O histórico de alergia ao contraste iodado precisa ser avaliado pelo radiologista, que decidirá como proceder.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/histerossalpingografia')),
    ('Histerossalpingografia', 'Tenho medo ou vaginismo. Existe alguma opção para a histerossalpingografia?', 'Avise a equipe ao agendar. Nesses casos pode ser indicada sedação ou outro cuidado para deixar o exame mais confortável. Você não precisa enfrentar sozinha.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/raio-x-contrastado/histerossalpingografia')),
    ('Histerossalpingografia', 'Como sai o resultado da histerossalpingografia?', 'O laudo mostra se as tubas estão abertas ou obstruídas e como está a cavidade do útero. Fica pronto conforme o prazo da unidade, e quem pediu o exame explica o que fazer.', ('Mater Prime', 'https://materprime.com.br/histerossalpingografia-hsg/')),
    ('Histerossalpingografia', 'Preciso me alimentar de forma especial antes da histerossalpingografia?', 'Algumas unidades pedem comer leve antes e um laxante suave na véspera. Siga o preparo da sua unidade, pois ele varia.', ('Mater Prime', 'https://materprime.com.br/histerossalpingografia-hsg/')),
    ('Cintilografia do miocárdio', 'Como é feita a cintilografia do miocárdio, em etapas?', 'Em geral são duas fases. Você recebe um radiofármaco na veia, aguarda e faz imagens em repouso. Depois faz esforço na esteira ou recebe um remédio que simula o esforço, e novas imagens são feitas para comparar com as primeiras.', ('IMEB', 'https://imeb.com.br/cintilografia-miocardica-como-e-feita/')),
    ('Cintilografia do miocárdio', 'Não consigo caminhar na esteira. Posso fazer a cintilografia do miocárdio?', 'Sim. Quando não é possível fazer esforço físico, existe o estresse farmacológico, em que um remédio aplicado na veia simula o esforço do coração. A equipe define o melhor tipo para você.', ('Quanta Diagnóstico por Imagem', 'https://quantadiagnostico.com/cintilografia-do-miocardio-perfusao-estresse-farmacologico/')),
    ('Cintilografia do miocárdio', 'O que vou sentir no estresse com remédio na cintilografia do miocárdio?', 'Podem ocorrer calor na cabeça, tontura, enjoo, dor de cabeça, falta de ar ou desconforto no peito, geralmente passageiros. Você é monitorado o tempo todo e deve avisar a equipe sobre qualquer sensação.', ('Tua Saúde', 'https://www.tuasaude.com/cintilografia-do-miocardio/')),
    ('Cintilografia do miocárdio', 'Tenho asma ou problema respiratório. Preciso avisar antes da cintilografia do miocárdio?', 'Sim. Doenças respiratórias, principalmente as mais graves, precisam ser conhecidas pela equipe, porque isso influencia a escolha do tipo de estresse. Informe no agendamento.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/medicina-nuclear/cintilografia-miocardio-perfusao-estresse-fisico')),
    ('Cintilografia do miocárdio', 'A radiação da cintilografia do miocárdio é perigosa?', 'O exame usa uma quantidade pequena e controlada de radiofármaco, seguindo normas de segurança. Ele é considerado seguro. Por precaução, grávidas e mulheres que amamentam devem avisar a equipe.', ('IMEB', 'https://imeb.com.br/cintilografia-miocardica-tire-suas-duvidas/')),
    ('Cintilografia do miocárdio', 'O que levar para a cintilografia do miocárdio?', 'Leve pedido médico, documento com foto, carteirinha do convênio, lista dos remédios em uso e exames do coração anteriores, como teste de esforço, ecocardiograma, cateterismo e outras cintilografias.', ('Quanta Diagnóstico por Imagem', 'https://quantadiagnostico.com/cintilografia-do-miocardio-perfusao-estresse-farmacologico/')),
    ('Cintilografia do miocárdio', 'Posso comer algo no intervalo entre as etapas da cintilografia do miocárdio?', 'Em geral sim, uma refeição leve é permitida e recomendada, sem jejum. Evite comidas gordurosas e tudo que tenha cafeína. Siga a orientação da equipe sobre o que trazer e quando comer.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/medicina-nuclear/cintilografia-miocardio-perfusao-estresse-fisico')),
    ('Cintilografia do miocárdio', 'Posso fumar ou beber álcool antes da cintilografia do miocárdio?', 'Alguns preparos pedem para evitar álcool, cigarro e alimentos com cafeína pelo tempo indicado no seu preparo. Siga esse período para não atrapalhar o exame.', ('MND Medicina Nuclear', 'https://www.grupomnd.com.br/site/preparos/6/cintilografia-do-miocardio-repouso-e-esforco/')),
    ('Cintilografia do miocárdio', 'Preciso levar toalha e calçado especial para a cintilografia do miocárdio?', 'Sim, se o teste for na esteira, use calçado fechado de sola de borracha e leve uma toalha de rosto. Roupa esportiva confortável facilita o esforço.', ('MND Medicina Nuclear', 'https://www.grupomnd.com.br/site/preparos/6/cintilografia-do-miocardio-repouso-e-esforco/')),
    ('Cintilografia do miocárdio', 'Preciso tirar os pelos do peito para a cintilografia do miocárdio?', 'Os eletrodos do eletrocardiograma precisam ficar bem colados, então pode ser necessário aparar os pelos do tórax. Tomar banho antes e esfoliar a pele do peito também ajuda o traçado.', ('MND Medicina Nuclear', 'https://www.grupomnd.com.br/site/preparos/6/cintilografia-do-miocardio-repouso-e-esforco/')),
    ('Cintilografia do miocárdio', 'Estou grávida e minha família vai me acompanhar. Alguma restrição para a cintilografia do miocárdio?', 'Gestantes não devem ficar acompanhando o exame por questões de proteção contra radiação. Menores de idade precisam de um responsável adulto durante o exame.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/medicina-nuclear/cintilografia-miocardio-perfusao-estresse-fisico')),
    ('Cintilografia do miocárdio', 'Tenho alergia. Preciso avisar antes da cintilografia do miocárdio?', 'Sim. Informe alergias, especialmente as graves e a medicamentos, para que a equipe se prepare com segurança.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/medicina-nuclear/cintilografia-miocardio-perfusao-estresse-fisico')),
    ('Cintilografia do miocárdio', 'Preciso ficar internado depois da cintilografia do miocárdio?', 'Não. É um exame ambulatorial e não exige internação. Você pode ter um intervalo de espera entre as etapas, e depois volta para casa conforme orientação da equipe.', ('Tua Saúde', 'https://www.tuasaude.com/cintilografia-do-miocardio/')),
    ('Cintilografia do miocárdio', 'Quando sai o resultado da cintilografia do miocárdio?', 'O laudo é liberado conforme o prazo informado pela unidade, depois que as imagens de repouso e de esforço são comparadas. Quem pediu o exame explicará o resultado.', ('IMEB', 'https://imeb.com.br/cintilografia-miocardica-tire-suas-duvidas/')),
    ('Cintilografia do miocárdio', 'Preciso dormir bem na véspera da cintilografia do miocárdio?', 'É recomendado. Uma boa noite de sono ajuda no desempenho durante o esforço e na tranquilidade do exame.', ('MND Medicina Nuclear', 'https://www.grupomnd.com.br/site/preparos/6/cintilografia-do-miocardio-repouso-e-esforco/')),
    ('Cintilografia da tireoide', 'Fiz tomografia ou exame com contraste recentemente. Isso atrapalha a cintilografia da tireoide?', 'Pode atrapalhar. Contrastes iodados de tomografia, urografia e outros exames ficam no corpo e podem prejudicar a captação da tireoide. Avise a equipe para que reorganizem a data conforme o intervalo indicado no seu preparo.', ('MND Medicina Nuclear', 'https://www.grupomnd.com.br/site/preparos/31/cintilografia-da-tireoide/')),
    ('Cintilografia da tireoide', 'Uso amiodarona ou outro remédio com iodo. Preciso avisar antes da cintilografia da tireoide?', 'Sim, é importante. Remédios que contêm iodo ou alteram a captação da tireoide podem exigir uma pausa longa, pelo tempo indicado no seu preparo. Não pare nada por conta própria e avise a equipe no agendamento.', ('Dimen Medicina Nuclear', 'https://www.dimen.com.br/lista-de-exames/cintilografia-da-tireoide-com-iodo-131-123/')),
    ('Cintilografia da tireoide', 'Tomo vitaminas e xaropes. Isso interfere na cintilografia da tireoide?', 'Podem interferir, principalmente vitaminas com iodo, xaropes para tosse e alguns outros remédios. Informe tudo o que usa para receber a orientação correta.', ('Saúde Naval', 'https://www.marinha.mil.br/saudenaval/cintilografia-de-tireoide')),
    ('Cintilografia da tireoide', 'A cintilografia da tireoide é feita em um dia só?', 'Em algumas unidades são dois momentos. Você recebe o radiofármaco e volta depois para as imagens, às vezes em mais de um horário. Confirme o cronograma no agendamento.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/medicina-nuclear/cintilografia-da-tireoide-ou-captacao-iodo-131')),
    ('Cintilografia da tireoide', 'Preciso fazer teste de gravidez antes da cintilografia da tireoide?', 'Mulheres em idade fértil podem precisar de um teste de gravidez recente. Gravidez é uma contraindicação e amamentação também deve ser informada.', ('Dimen Medicina Nuclear', 'https://www.dimen.com.br/lista-de-exames/cintilografia-da-tireoide-com-iodo-131-123/')),
    ('Cintilografia da tireoide', 'Esmalte, bronzeador e protetor solar atrapalham a cintilografia da tireoide?', 'Esmalte com base, bronzeador, iodo na pele e maquiagem vermelha devem ser evitados pelo tempo indicado no seu preparo. Uma unidade cita que protetor solar é permitido, mas confirme a sua.', ('MND Medicina Nuclear', 'https://www.grupomnd.com.br/site/preparos/31/cintilografia-da-tireoide/')),
    ('Cintilografia da tireoide', 'Tenho alergia a iodo. Posso fazer a cintilografia da tireoide?', 'Em geral a quantidade usada é mínima e não costuma causar reações. Ainda assim, avise a equipe sobre qualquer alergia antes do exame.', ('CDC Nuclear', 'https://cdcnuclear.com.br/exames/cintilografia-de-tireoide/')),
    ('Cintilografia da tireoide', 'Vou sentir algo depois de tomar o radiofármaco na cintilografia da tireoide?', 'Em geral são efeitos leves, como coceira, vermelhidão, boca seca e mudança no paladar, porque as glândulas salivares também eliminam parte do produto.', ('Dimen Medicina Nuclear', 'https://www.dimen.com.br/lista-de-exames/cintilografia-da-tireoide-com-iodo-131-123/')),
    ('Cintilografia da tireoide', 'O que devo levar para a cintilografia da tireoide?', 'Leve pedido médico, documento com foto, carteirinha do convênio, exames de sangue da tireoide e ultrassom do pescoço anteriores. Esses exames ajudam na comparação com as imagens.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/medicina-nuclear/cintilografia-da-tireoide-ou-captacao-iodo-131')),
    ('Cintilografia da tireoide', 'Como é feita a cintilografia da tireoide?', 'Você recebe um radiofármaco, por via oral ou pela veia, e aguarda. Depois deita para uma câmera captar as imagens da glândula. Áreas mais ativas aparecem mais brilhantes.', ('Dasa', 'https://nav.dasa.com.br/blog/cintilografia-da-tireoide')),
    ('Cintilografia da tireoide', 'Posso tomar banho de mar ou fazer exame ginecológico antes da cintilografia da tireoide?', 'Algumas unidades pedem para evitar banho de mar e procedimentos ginecológicos com iodo antes do exame. Siga o período do seu preparo.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/medicina-nuclear/cintilografia-da-tireoide-ou-captacao-iodo-131')),
    ('Cintilografia da tireoide', 'Grávida pode me acompanhar na cintilografia da tireoide?', 'Não, por proteção contra radiação. Menores de idade precisam de um responsável adulto durante o exame.', ("Rede D'Or São Luiz", 'https://www.rededorsaoluiz.com.br/exames-e-procedimentos/medicina-nuclear/cintilografia-da-tireoide-ou-captacao-iodo-131')),
    ('Cintilografia da tireoide', 'Quando posso voltar à alimentação normal depois da cintilografia da tireoide?', 'Em geral, depois das imagens finais você retoma a alimentação habitual, a não ser que faça outro tratamento com iodo em seguida. Siga a orientação da equipe.', ('Dimen Medicina Nuclear', 'https://www.dimen.com.br/lista-de-exames/cintilografia-da-tireoide-com-iodo-131-123/')),
    ('Cintilografia da tireoide', 'Preciso avisar sobre remédio para tireoide que não pude parar?', 'Sim. Não interrompa remédios por conta própria e avise a equipe de tudo que usa, para saber se o exame precisa ser adiado ou adaptado.', ('Nucleomed Medicina Nuclear', 'https://www.nucleomedicinanuclear.com.br/orientacoes/orientatireoREVISAO1.pdf')),
    ('Cintilografia da tireoide', 'Por que o preparo da cintilografia da tireoide é tão exigente?', 'Porque iodo em alimentos, remédios e produtos de pele pode alterar a captação da glândula e comprometer as imagens. Seguir tudo à risca evita ter que repetir o exame.', ('Dasa', 'https://nav.dasa.com.br/blog/cintilografia-da-tireoide')),
    ('Cintilografia óssea', 'Preciso esvaziar a bexiga durante a cintilografia óssea?', 'Sim. Na espera após a injeção você deve urinar várias vezes, porque isso ajuda a eliminar o produto que não ficou nos ossos e deixa as imagens melhores. Não é preciso chegar com a bexiga cheia.', ('Photon Medicina Nuclear', 'https://photonmedicinanuclear.com.br/upload/exames/Musculoesqueletico/CintilografiaOssea_Com_Sem_Fluxo.pdf')),
    ('Cintilografia óssea', 'Posso sair da clínica entre a injeção e as imagens da cintilografia óssea?', 'Em geral sim. Depois da injeção há um intervalo de espera, e muitos serviços permitem que você faça suas atividades, desde que volte no horário e mantenha a hidratação.', ('Centrocor', 'https://www.centrocor.com.br/cintilografia-ossea')),
    ('Cintilografia óssea', 'O que posso beber na espera da cintilografia óssea?', 'Água é a melhor opção. Alguns serviços aceitam também suco. O importante é tomar bastante líquido durante a espera, salvo se você tiver restrição de líquidos.', ('Photon Medicina Nuclear', 'https://photonmedicinanuclear.com.br/upload/exames/Musculoesqueletico/CintilografiaOssea_Com_Sem_Fluxo.pdf')),
    ('Cintilografia óssea', 'Tenho problema no rim ou no coração. Preciso me hidratar muito para a cintilografia óssea?', 'Nesses casos a hidratação abundante pode não ser indicada. Avise a equipe antes para que orientem a quantidade adequada para você.', ('Dimen Medicina Nuclear', 'https://www.dimen.com.br/lista-de-exames/cintilografia-ossea/')),
    ('Cintilografia óssea', 'Que roupa devo usar na cintilografia óssea?', 'Use roupa confortável, sem excesso de botões ou peças de metal. Evite cinto com fivela, joias, brincos e pulseiras. Em alguns locais é pedido retirar essas peças antes das imagens.', ('CDC Nuclear', 'https://cdcnuclear.com.br/exames/cintilografia-ossea/')),
    ('Cintilografia óssea', 'Tenho medo de lugar fechado. Posso fazer a cintilografia óssea?', 'Avise a equipe. O equipamento fica bem próximo ao corpo, mas você não fica dentro de um túnel fechado, e a equipe pode ajudar a deixar o exame mais confortável.', ('Ortopedia e Ombro', 'https://ortopediaeombro.com.br/cintilografia-ossea/')),
    ('Cintilografia óssea', 'O que levar para a cintilografia óssea?', 'Leve pedido médico, documento com foto, carteirinha do convênio e exames anteriores relacionados ao caso, como radiografias, tomografias, ressonâncias e outras cintilografias.', ('CDC Nuclear', 'https://cdcnuclear.com.br/exames/cintilografia-ossea/')),
    ('Cintilografia óssea', 'Quanto tempo dura a cintilografia óssea no total?', 'O exame tem um intervalo de espera após a injeção e depois as imagens. O tempo total é longo, mas você pode se ausentar durante a espera, e a captura das imagens é a parte mais curta.', ('Blog CDB', 'https://blog.cdb.com.br/cintilografia-ossea-para-que-serve-e-como-e-feito-o-exame/')),
    ('Cintilografia óssea', 'A injeção da cintilografia óssea dói? Posso ter algum efeito?', 'Você sente apenas a picada da veia, e pode haver um leve desconforto no local. Efeitos gerais são raros e podem incluir enjoo, dor de cabeça ou febre. Avise a equipe se sentir algo.', ('Dimen Medicina Nuclear', 'https://www.dimen.com.br/lista-de-exames/cintilografia-ossea/')),
    ('Cintilografia óssea', 'Como sai o resultado da cintilografia óssea?', 'Um especialista analisa as imagens com cuidado e emite o laudo, entregue conforme o prazo da unidade. Não há resultado na hora.', ('Blog CDB', 'https://blog.cdb.com.br/cintilografia-ossea-para-que-serve-e-como-e-feito-o-exame/')),
    ('Cintilografia óssea', 'Posso voltar à rotina depois da cintilografia óssea?', 'Em geral sim, não há restrições de atividade. Continue se hidratando para eliminar o produto que não se fixou nos ossos.', ('Blog CDB', 'https://blog.cdb.com.br/cintilografia-ossea-para-que-serve-e-como-e-feito-o-exame/')),
    ('Cintilografia óssea', 'Grávida ou criança pode me acompanhar na cintilografia óssea?', 'Não é recomendado. Por proteção contra radiação, gestantes e crianças não devem acompanhar o procedimento. Evite contato próximo com elas logo depois, pelo tempo que a equipe orientar.', ('Centrocor', 'https://www.centrocor.com.br/cintilografia-ossea')),
    ('Cintilografia óssea', 'Fiz uma cintilografia trifásica. Por que as imagens começam logo na injeção?', 'Na cintilografia com fase de fluxo, algumas imagens são feitas já durante a aplicação do radiofármaco, e as demais vêm depois, na fase tardia.', ('Photon Medicina Nuclear', 'https://photonmedicinanuclear.com.br/upload/exames/Musculoesqueletico/CintilografiaOssea_Com_Sem_Fluxo.pdf')),
    ('Cintilografia óssea', 'Preciso mudar minha alimentação na cintilografia óssea?', 'Não. A dieta habitual é mantida, sem jejum, e os remédios de uso contínuo seguem normalmente, salvo orientação diferente da equipe.', ('Centrocor', 'https://www.centrocor.com.br/cintilografia-ossea')),
    ('Cintilografia óssea', 'Tenho alergia a algum produto usado em exames. Preciso avisar na cintilografia óssea?', 'Sim. Conte à equipe se já teve reação a radiofármacos ou outros produtos de exames.', ('Ortopedia e Ombro', 'https://ortopediaeombro.com.br/cintilografia-ossea/')),
]
